import{_ as i,o as a,c as l,ag as p}from"./chunks/framework.PVHj0As1.js";const t="/pub-blog/assets/image-20241030202356771.Bx989WhK.png",n="/pub-blog/assets/image-20241030204135638.BCQzZeAH.png",e="/pub-blog/assets/image-20241030221519493.CqTn599g.png",h="/pub-blog/assets/PixPin_2024-10-30_22-18-52.Dw1QbGQ5.gif",r="/pub-blog/assets/PixPin_2024-10-30_22-25-22.BiFvuSwk.gif",k="/pub-blog/assets/PixPin_2024-10-30_23-36-42.DcsoVc0G.gif",E="/pub-blog/assets/PixPin_2024-10-30_23-39-43.XdcdWFnq.gif",d="/pub-blog/assets/PixPin_2024-10-30_23-53-22.amrrXi6d.gif",o="/pub-blog/assets/PixPin_2024-10-31_00-00-34.Bpp17PqF.gif",c="/pub-blog/assets/image-20241031000618657.C9S7Ahxd.png",A=JSON.parse("{\"title\":\"HarmonyOS Next 关于页面渲染的性能优化方案\",\"description\":\"\",\"frontmatter\":{},\"headers\":[],\"relativePath\":\"鸿蒙开发技巧/HarmonyOS Next 关于页面渲染的性能优化方案/HarmonyOS Next 关于页面渲染的性能优化方案.md\",\"filePath\":\"鸿蒙开发技巧/HarmonyOS Next 关于页面渲染的性能优化方案/HarmonyOS Next 关于页面渲染的性能优化方案.md\",\"lastUpdated\":1730788610000,\"__rawMarkdown\":\"# HarmonyOS Next 关于页面渲染的性能优化方案\\n\\n**HarmonyOS Next**  应用开发中，用户的使用体验至关重要。其中用户启动**APP**到呈现页面主要包含三个步骤：\\n\\n1. 框架初始化\\n2. 页面加载\\n3. 布局渲染\\n\\n![image-20241030202356771](HarmonyOS%20Next%20%E5%85%B3%E4%BA%8E%E9%A1%B5%E9%9D%A2%E6%B8%B2%E6%9F%93%E7%9A%84%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E6%96%B9%E6%A1%88.assets/image-20241030202356771.png)\\n\\n从**页面加载**到**布局渲染**中，主要包含了6个环节：\\n\\n1. 执行页面文件\\n2. 生成页面节点树\\n3. **页面节点树挂载**\\n4. 布局\\n5. **渲染**\\n6. 展示\\n\\n页面节点树挂载的速度取决于节点的数量，我们可以理解给1个自定义组件在渲染时，后端同时会生成一个对应的\\n\\n节点。该节点后期会用来**diff**。\\n\\n**渲染**的速度取决于布局属性。如果布局属性越复杂、冗余。那么就越慢。\\n\\n\\n\\n# 节点的数量优化\\n\\n**HarmonyOS Next** 会根据自定义节点的数量在后端生成对应的节点。那么如果我们在实际开发中，可以考虑尽量的将自定义组件的数量减少，替换成 **@Builder** 自定义构建函数。\\n\\n那么哪些自定义节点可以替换成**@Builder**自定义构建函数呢，看下表：\\n\\n| 分类         | 自定义组件 | @Builder   |\\n| ------------ | ---------- | ---------- |\\n| 复用布局结构 | 支持       | 支持       |\\n| 复用样式     | 支持       | 支持       |\\n| 导出使用     | 支持       | **不支持** |\\n| 生命周期     | 支持       | **不支持** |\\n| 状态管理     | 支持       | **不支持** |\\n\\n所以，当我们对于封装的需求，不需要导出使用、不需要使用生命周期、不需要独立的状态管理时。就可以使用**@Builder**来代替自定义组件。\\n\\n\\n\\n## @Builder的基本使用\\n\\n![image-20241030204135638](HarmonyOS%20Next%20%E5%85%B3%E4%BA%8E%E9%A1%B5%E9%9D%A2%E6%B8%B2%E6%9F%93%E7%9A%84%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E6%96%B9%E6%A1%88.assets/image-20241030204135638.png)\\n\\n```typescript\\n@Entry\\n@Component\\nstruct Index {\\n  @Builder\\n  CustomBtn(text:string){\\n    Button(text)\\n      .width(100)\\n      .height(50)\\n      .linearGradient({\\n        colors:[[Color.Black,0],[Color.Red,1]]\\n      })\\n  }\\n\\n  build() {\\n    Column({space:10}){\\n      this.CustomBtn(\\\"登录\\\")\\n      this.CustomBtn(\\\"注册\\\")\\n\\n    }\\n    .width(\\\"100%\\\")\\n    .height(\\\"100%\\\")\\n    .justifyContent(FlexAlign.Center)\\n  }\\n}\\n```\\n\\n## 自定义组件的基本使用\\n\\n![image-20241030204135638](HarmonyOS%20Next%20%E5%85%B3%E4%BA%8E%E9%A1%B5%E9%9D%A2%E6%B8%B2%E6%9F%93%E7%9A%84%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E6%96%B9%E6%A1%88.assets/image-20241030204135638.png)\\n\\n```typescript\\n@Component\\nstruct CustomBtn {\\n  text: string = \\\"\\\"\\n\\n  build() {\\n    Button(this.text)\\n      .width(100)\\n      .height(50)\\n      .linearGradient({\\n        colors: [[Color.Black, 0], [Color.Red, 1]]\\n      })\\n  }\\n}\\n\\n@Entry\\n@Component\\nstruct Index {\\n  build() {\\n    Column({ space: 10 }) {\\n      CustomBtn({text:\\\"登录\\\"})\\n      CustomBtn({text:\\\"注册\\\"})\\n\\n    }\\n    .width(\\\"100%\\\")\\n    .height(\\\"100%\\\")\\n    .justifyContent(FlexAlign.Center)\\n  }\\n}\\n```\\n\\n\\n\\n# 布局属性的优化\\n\\n这里的优化，主要是指性能的优化，也就是用户体验的优化，不是对于开发者来讲的开发体验的优化。\\n\\n**HarmonyOS Next**  有提供 **@Styles** 和 **@Extends** 来实现代码层面的优化，也就是样式代码的简单封装。\\n\\n但是无论是用户层面的优化和代码层面的优化。**@Styles** **和 @Extends** 都存在一定的限制。因此**HarmonyOS**\\n\\n**Next** 又推出了 **AttributeModifier**  和  **AttributeUpdater**(AttributeUpdater 是AttributeModifier的继承 )\\n\\n\\n\\n# AttributeModifier \\n\\n1. **AttributeModifier**是一个接口，需要我们主动实现它相关的方法。如默认态(Normal)、按压态(Pressed)、焦点态(Focused)、禁用态(Disabled)、选择态(Selected)\\n2. **AttributeModifier** 可以实现样式属性的按需注册\\n3. 支持和@**Observed**和@**ObjectLink**配套使用\\n\\n\\n\\n## AttributeModifier 基本使用\\n\\n1. 定义**MyButtonModifier**类，继承**AttributeModifier**接口，并且声明是对**Button**进行的样式属性封装\\n\\n   ```typescript\\n   export class MyButtonModifier implements AttributeModifier<ButtonAttribute> {\\n   ```\\n\\n2. **MyButtonModifier**中声明变量，用来注册不同的样式属性\\n\\n   ```typescript\\n   isDark: boolean = false\\n   ```\\n\\n3. 定义正常态的样式 （**applyNormalAttribute** 是接口**AttributeModifier**中定义的 ）\\n\\n   ```typescript\\n     applyNormalAttribute(instance: ButtonAttribute): void {\\n       if (this.isDark) {\\n         instance.backgroundColor(Color.Black)\\n           .fontColor(Color.White)\\n           .border({\\n             width:10,\\n             color:Color.Brown\\n           })\\n           .borderRadius(20)\\n           .padding(10)\\n           .margin(20)\\n       } else {\\n         instance.backgroundColor(Color.White)\\n           .fontColor(Color.Black)\\n       }\\n     }\\n   ```\\n\\n   ![image-20241030221519493](HarmonyOS%20Next%20%E5%85%B3%E4%BA%8E%E9%A1%B5%E9%9D%A2%E6%B8%B2%E6%9F%93%E7%9A%84%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E6%96%B9%E6%A1%88.assets/image-20241030221519493.png)\\n\\n4. 组件中开始复用(完整代码)\\n\\n   ```typescript\\n   export class MyButtonModifier implements AttributeModifier<ButtonAttribute> {\\n     isDark: boolean = false\\n     constructor(dark?: boolean) {\\n       this.isDark = !!dark\\n     }\\n     applyNormalAttribute(instance: ButtonAttribute): void {\\n       if (this.isDark) {\\n         instance.backgroundColor(Color.Black)\\n           .fontColor(Color.White)\\n           .border({\\n             width:10,\\n             color:Color.Brown\\n           })\\n           .borderRadius(20)\\n           .padding(10)\\n           .margin(20)\\n       } else {\\n         instance.backgroundColor(Color.White)\\n           .fontColor(Color.Black)\\n       }\\n     }\\n   }\\n   \\n   \\n   @Entry\\n   @Component\\n   struct attributeDemo {\\n     @State modifier: MyButtonModifier = new MyButtonModifier(false);\\n   \\n     build() {\\n       Row() {\\n         Column() {\\n           Button(\\\"Button\\\")\\n             // 注册属性\\n             .attributeModifier(this.modifier)\\n             .onClick(() => {\\n               // 点击切换\\n               this.modifier.isDark = !this.modifier.isDark\\n             })\\n         }\\n         .width('100%')\\n       }\\n       .height('100%')\\n     }\\n   }\\n   ```\\n\\n5. 效果\\n\\n   ![PixPin_2024-10-30_22-18-52](HarmonyOS%20Next%20%E5%85%B3%E4%BA%8E%E9%A1%B5%E9%9D%A2%E6%B8%B2%E6%9F%93%E7%9A%84%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E6%96%B9%E6%A1%88.assets/PixPin_2024-10-30_22-18-52.gif)\\n\\n\\n\\n## AttributeModifier 其他状态\\n\\n多态样式中除了默认态(Normal)还有 、按压态(Pressed)、焦点态(Focused)、禁用态(Disabled)、选择态(Selected)。我们一并实现。\\n\\n```typescript\\n  // 按压\\n  applyPressedAttribute(instance: ButtonAttribute): void {\\n    instance\\n      .backgroundColor(Color.Red)\\n  }\\n  // 获得焦点\\n  applyFocusedAttribute(instance: ButtonAttribute): void {\\n  }\\n  // 选择\\n  applySelectedAttribute(instance: ButtonAttribute): void {\\n  }\\n  // 禁用\\n  applyDisabledAttribute(instance: ButtonAttribute): void {\\n  }\\n```\\n\\n![PixPin_2024-10-30_22-25-22](HarmonyOS%20Next%20%E5%85%B3%E4%BA%8E%E9%A1%B5%E9%9D%A2%E6%B8%B2%E6%9F%93%E7%9A%84%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E6%96%B9%E6%A1%88.assets/PixPin_2024-10-30_22-25-22.gif)\\n\\n## 搭配 @Observed和@ObjectLink\\n\\n上述案例中，样式的变更是根据 变量 **isDark**来实现的。如果想要根据对象中某个属性来实现样式的变更。我们可以搭配@**Observed**和@**ObjectLink**\\n\\n### 对象嵌套对象\\n\\n以下代码主要利用了 @**Observed**和@**ObjectLink** 可以监听深层次属性的改变，然后当深层次属性改变后，触发\\n\\n**AttributeModifier** 跟随改变。\\n\\n1. 声明子类 **Son**，代表深层次属性的载体\\n\\n   ```typescript\\n   @Observed\\n   class Son {\\n     // 控制样式切换的关键变量\\n     isShow: boolean = false\\n   }\\n   ```\\n\\n2. 使用  **@Observed** 修饰 **Person**类 (父类)，拥有**Son**子类\\n\\n   ```typescript\\n   @Observed\\n   class Person {\\n     son: Son = new Son()\\n   }\\n   ```\\n\\n3. 声明 **BtnModifier** 类，需要实现 **AttributeModifier** 接口，实现样式优化和复用。接收 son属性。用来响应状态变化\\n\\n   ```\\n   class BtnModifier implements AttributeModifier<ButtonAttribute> {\\n     son: Son\\n   \\n     constructor(son: Son) {\\n       this.son = son\\n     }\\n   \\n     applyNormalAttribute(instance: ButtonAttribute): void {\\n       if (this.son.isShow) {\\n         instance.backgroundColor(Color.Red)\\n       } else {\\n         instance.backgroundColor(Color.Green)\\n       }\\n     }\\n   }\\n   ```\\n\\n4. 完整代码\\n\\n   ```typescript\\n   import { promptAction } from '@kit.ArkUI';\\n   \\n   // 定义一个名为 'BtnModifier' 的类，实现对 'ButtonAttribute' 的属性修改\\n   class BtnModifier implements AttributeModifier<ButtonAttribute> {\\n     // 存储一个 'Son' 类型的实例\\n     son: Son;\\n   \\n     // 构造函数，接收一个 'Son' 类型的参数并初始化 'son' 属性\\n     constructor(son: Son) {\\n       this.son = son;\\n     }\\n   \\n     // 应用普通属性的方法，接收一个 'ButtonAttribute' 类型的实例作为参数\\n     applyNormalAttribute(instance: ButtonAttribute): void {\\n       // 如果 'son' 的 'isShow' 属性为 true，则将按钮背景颜色设置为红色\\n       if (this.son.isShow) {\\n         instance.backgroundColor(Color.Red);\\n       } else {\\n         // 否则将按钮背景颜色设置为绿色\\n         instance.backgroundColor(Color.Green);\\n       }\\n     }\\n   }\\n   \\n   // 使用 '@Observed' 装饰器标记的类，表示该类的变化可以被观测到\\n   @Observed\\n   class Son {\\n     // 定义一个布尔类型的属性 'isShow'，初始值为 false\\n     isShow: boolean = false;\\n   }\\n   \\n   // 使用 '@Observed' 装饰器标记的类，表示该类的变化可以被观测到\\n   @Observed\\n   class Person {\\n     // 创建一个 'Son' 类型的实例并初始化\\n     son: Son = new Son();\\n   }\\n   \\n   @Component\\n   struct CustomBtn {\\n     // 使用 '@ObjectLink' 装饰器标记的属性，表示与外部对象的链接\\n     @ObjectLink\\n     son: Son;\\n     // 可空的 'BtnModifier' 类型属性\\n     modify: BtnModifier | null = null;\\n   \\n     // 在组件即将出现时执行的方法\\n     aboutToAppear(): void {\\n       // 创建一个新的 'BtnModifier' 实例并赋值给 'modify' 属性\\n       this.modify = new BtnModifier(this.son);\\n     }\\n   \\n     // 构建组件的方法\\n     build() {\\n       // 创建一个按钮，并将按钮的文本设置为 'son.isShow' 的字符串表示形式\\n       Button(this.son.isShow.toString())// 设置按钮的属性修改器为 'modify'\\n         .attributeModifier(this.modify);\\n     }\\n   }\\n   \\n   @Entry\\n   @Component\\n   struct Index {\\n     // 使用 '@State' 装饰器标记的属性，表示该属性的变化会触发组件的重新渲染\\n     @State\\n     person: Person = new Person();\\n   \\n     build() {\\n       // 创建一个列容器\\n       Column() {\\n         // 创建一个自定义按钮组件，并传入 'person.son' 作为参数\\n         CustomBtn({ son: this.person.son })// 为按钮添加点击事件处理函数\\n           .onClick(() => {\\n             // 切换 'person.son.isShow' 的值\\n             this.person.son.isShow = !this.person.son.isShow;\\n             // 显示一个提示信息\\n             promptAction.showToast({ message: `${this.person.son.isShow}` });\\n           });\\n       }\\n       .width(\\\"100%\\\")\\n       .height(\\\"100%\\\")\\n       .justifyContent(FlexAlign.Center);\\n     }\\n   }\\n   \\n   ```\\n\\n   ---\\n\\n   ![PixPin_2024-10-30_23-36-42](HarmonyOS%20Next%20%E5%85%B3%E4%BA%8E%E9%A1%B5%E9%9D%A2%E6%B8%B2%E6%9F%93%E7%9A%84%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E6%96%B9%E6%A1%88.assets/PixPin_2024-10-30_23-36-42.gif)\\n\\n\\n\\n\\n\\n### 数组嵌套对象\\n\\n数组嵌套对象的写法类似上面示例，但是可以通过简单的一些编程技巧来进一步优化。如单例\\n\\n```typescript\\n// 定义一个名为 'BtnModifier' 的类，实现对 'ButtonAttribute' 的属性修改\\nclass BtnModifier implements AttributeModifier<ButtonAttribute> {\\n  // 静态变量，用于存储单例实例\\n  static instance: BtnModifier;\\n  // 表示是否在交谈的布尔属性，初始值为 false\\n  isTalk: boolean = false;\\n\\n  // 静态方法，用于获取单例实例\\n  static getInstance(): BtnModifier {\\n    // 如果单例实例不存在，则创建一个新的实例\\n    if (!BtnModifier.instance) {\\n      BtnModifier.instance = new BtnModifier();\\n    }\\n    // 返回单例实例\\n    return BtnModifier.instance;\\n  }\\n\\n  // 设置 isTalk 属性的方法\\n  setTalk(isTalk: boolean): BtnModifier {\\n    // 更新 isTalk 属性值\\n    this.isTalk = isTalk;\\n    // 返回当前实例，以便进行链式调用\\n    return this;\\n  }\\n\\n  // 应用普通属性的方法，接收一个 'ButtonAttribute' 类型的实例作为参数\\n  applyNormalAttribute(instance: ButtonAttribute): void {\\n    // 如果 isTalk 为 true，则将按钮背景颜色设置为红色\\n    if (this.isTalk) {\\n      instance.backgroundColor(Color.Red);\\n    } else {\\n      // 否则将按钮背景颜色设置为绿色\\n      instance.backgroundColor(Color.Green);\\n    }\\n  }\\n}\\n\\n// 使用 '@Observed' 装饰器标记的类，表示该类的变化可以被观测到\\n@Observed\\nclass Person {\\n  // 用户名属性，初始值为 \\\"人类\\\"\\n  userName: string = \\\"人类\\\";\\n  // 表示是否在交谈的布尔属性，初始值为 false\\n  isTalk: boolean = false;\\n}\\n\\n@Component\\nstruct CustomBtn {\\n  // 使用 '@ObjectLink' 装饰器标记的属性，表示与外部对象的链接\\n  @ObjectLink\\n  person: Person;\\n  // 存储 'BtnModifier' 的实例，通过单例模式获取\\n  modify: BtnModifier = BtnModifier.getInstance();\\n\\n  // 构建组件的方法\\n  build() {\\n    // 创建一个按钮，并将按钮的文本设置为 'person.userName'\\n    Button(this.person.userName)// 设置按钮的属性修改器，并根据 'person.isTalk' 的值设置是否在交谈状态\\n      .attributeModifier(this.modify.setTalk(this.person.isTalk));\\n  }\\n}\\n\\n@Entry\\n@Component\\nstruct Index {\\n  // 使用 '@State' 装饰器标记的属性，表示该属性的变化会触发组件的重新渲染\\n  @State\\n  personList: Person[] = [new Person(), new Person()];\\n\\n  // 构建组件的方法\\n  build() {\\n    // 创建一个列容器\\n    Column() {\\n      // 遍历 'personList'，为每个 'Person' 实例创建一个 'CustomBtn' 组件，并添加点击事件处理函数\\n      ForEach(this.personList, (person: Person) => {\\n        CustomBtn({ person: person })\\n          .onClick(() => {\\n            // 切换 'person.isTalk' 的值\\n            person.isTalk = !person.isTalk;\\n          });\\n      });\\n    }\\n    .width(\\\"100%\\\")\\n    .height(\\\"100%\\\")\\n    .justifyContent(FlexAlign.Center);\\n  }\\n}\\n\\n```\\n\\n---\\n\\n![PixPin_2024-10-30_23-39-43](HarmonyOS%20Next%20%E5%85%B3%E4%BA%8E%E9%A1%B5%E9%9D%A2%E6%B8%B2%E6%9F%93%E7%9A%84%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E6%96%B9%E6%A1%88.assets/PixPin_2024-10-30_23-39-43.gif)\\n\\n\\n\\n\\n\\n## AttributeModifier 和 @Styles 、@Extend的比较\\n\\n| 能力             | @Styles | @Extend | AttributeModifier |\\n| ---------------- | ------- | ------- | ----------------- |\\n| 跨文件导出       | 不支持  | 不支持  | 支持              |\\n| 通用属性设置     | 支持    | 支持    | 支持              |\\n| 通用事件设置     | 支持    | 支持    | 部分支持          |\\n| 组件特有属性设置 | 不支持  | 支持    | 部分支持          |\\n| 组件特有事件设置 | 不支持  | 支持    | 部分支持          |\\n| 参数传递         | 不支持  | 支持    | 支持              |\\n| 多态样式         | 支持    | 不支持  | 支持              |\\n| 业务逻辑         | 不支持  | 不支持  | 支持              |\\n\\n 基于以上对比，可以看见  **AttributeModifier** 几乎可以满足以上所有场景。唯一缺点就是代码量稍多一些些。\\n\\n\\n\\n## 接口定义\\n\\n```typescript\\ndeclare interface AttributeModifier<T> {\\n\\n  applyNormalAttribute?(instance: T): void;\\n  \\n  applyPressedAttribute?(instance: T): void;\\n  \\n  applyFocusedAttribute?(instance: T): void;\\n  \\n  applyDisabledAttribute?(instance: T): void;\\n  \\n  applySelectedAttribute?(instance: T): void;\\n\\n}\\n```\\n\\n\\n\\n# AttributeUpdater\\n\\n如果设计大量的样式属性修改，如果都是基于状态变量，那么在实现修改前，还是会导致diff的对比，性能损耗验证。因此引入了 **AttributeUpdater**，它继承了**AttributeModifier**基本能力，还拓展了直接修改属性和组件构造函数的能力。用来根据单一状态来批量修改样式属性。\\n\\n\\n\\n## 简单实用\\n\\n1. 声明 **MyButtonUpdater** 类，继承 **AttributeUpdater**\\n2. 组件中实例化 **MyButtonUpdater**  类\\n3. 直接修改组件样式属性\\n\\n```typescript\\nimport { AttributeUpdater } from '@kit.ArkUI';\\n\\n// 注意，这里是继承  AttributeUpdater 类\\nclass MyButtonUpdater extends AttributeUpdater<ButtonAttribute> {\\n}\\n\\n@Entry\\n@Component\\nstruct attributeDemo {\\n  @State modifier: MyButtonUpdater = new MyButtonUpdater();\\n\\n  build() {\\n    Row() {\\n      Column() {\\n        Button(\\\"直接修改批量样式属性\\\")\\n          .attributeModifier(this.modifier)\\n          .onClick(() => {\\n            // 直接修改\\n            this.modifier.attribute?.backgroundColor(Color.Green).width(200).fontColor(Color.Red)\\n          })\\n      }\\n      .width('100%')\\n    }\\n    .height('100%')\\n  }\\n}\\n```\\n\\n---\\n\\n![PixPin_2024-10-30_23-53-22](HarmonyOS%20Next%20%E5%85%B3%E4%BA%8E%E9%A1%B5%E9%9D%A2%E6%B8%B2%E6%9F%93%E7%9A%84%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E6%96%B9%E6%A1%88.assets/PixPin_2024-10-30_23-53-22.gif)\\n\\n## 重新调用组件构造函数\\n\\n提供了`updateConstructorParams` 接口，可以让我们重新调用该组件的构造函数。实现组件的重新渲染\\n\\n1. 继承 **AttributeUpdater** 类时，同时传入两个泛型 **ButtonAttribute** 和  **ButtonInterface**\\n\\n   ```\\n   class MyButtonUpdater extends AttributeUpdater<ButtonAttribute,ButtonInterface> {\\n   \\n   }\\n   ```\\n\\n2. 直接调用要组件的构造函数 **updateConstructorParams**\\n\\n   ```\\n   import { AttributeUpdater } from '@kit.ArkUI';\\n   \\n   // 注意，这里是继承  AttributeUpdater 类\\n   class MyButtonUpdater extends AttributeUpdater<ButtonAttribute,ButtonInterface> {\\n   \\n   }\\n   \\n   @Entry\\n   @Component\\n   struct attributeDemo {\\n     @State modifier: MyButtonUpdater = new MyButtonUpdater();\\n   \\n     build() {\\n       Row() {\\n         Column() {\\n           Button(\\\"重新渲染组件\\\")\\n             .attributeModifier(this.modifier)\\n             .onClick(() => {\\n               this.modifier.updateConstructorParams(\\\"文本也可以改变\\\")\\n             })\\n         }\\n         .width('100%')\\n       }\\n       .height('100%')\\n     }\\n   }\\n   ```\\n\\n   ---\\n\\n   ![PixPin_2024-10-31_00-00-34](HarmonyOS%20Next%20%E5%85%B3%E4%BA%8E%E9%A1%B5%E9%9D%A2%E6%B8%B2%E6%9F%93%E7%9A%84%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E6%96%B9%E6%A1%88.assets/PixPin_2024-10-31_00-00-34.gif)\\n\\n## 接口定义\\n\\n```\\nexport declare class AttributeUpdater<T, C = Initializer<T>> implements AttributeModifier<T> {\\n  applyNormalAttribute?(instance: T): void;\\n  initializeModifier(instance: T): void;\\n  get attribute(): T | undefined;\\n  updateConstructorParams: C;\\n}\\n```\\n\\n\\n\\n\\n\\n# 总结\\n\\n后期如果要考虑实现样式复用，可以优先使用 AttributeModifier  和 AttributeUpdater\\n\\n![image-20241031000618657](HarmonyOS%20Next%20%E5%85%B3%E4%BA%8E%E9%A1%B5%E9%9D%A2%E6%B8%B2%E6%9F%93%E7%9A%84%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E6%96%B9%E6%A1%88.assets/image-20241031000618657.png)\"}"),b={name:"鸿蒙开发技巧/HarmonyOS Next 关于页面渲染的性能优化方案/HarmonyOS Next 关于页面渲染的性能优化方案.md"};function g(y,s,u,m,F,C){return a(),l("div",null,[...s[0]||(s[0]=[p("",64)])])}const D=i(b,[["render",g]]);export{A as __pageData,D as default};
